#!/usr/bin/env bash
# Writes .env.local from the running local stack. User overrides belong in .env, which loads first and wins.
set -euo pipefail
cd "$(dirname "$0")/.."

pnpm exec supabase status -o json | node -e '
  const fs = require("node:fs");
  const status = JSON.parse(fs.readFileSync(0, "utf8"));
  const pick = (key) => {
    if (!status[key]) throw new Error(`supabase status did not report ${key}`);
    return status[key];
  };
  const lines = [
    "# Generated by scripts/write-env.sh from the local Supabase stack. Do not edit, put overrides in .env.",
    `DATABASE_URL=${pick("DB_URL")}`,
    `SUPABASE_URL=${pick("API_URL")}`,
    `SUPABASE_PUBLISHABLE_KEY=${pick("PUBLISHABLE_KEY")}`,
    `SUPABASE_SECRET_KEY=${pick("SECRET_KEY")}`,
  ];
  fs.writeFileSync(".env.local", lines.join("\n") + "\n");
'
echo "Wrote .env.local"
